public class Main {
    static abstract class Report {
        protected final String title;
        Report(String title) { this.title = title; }
        abstract String body();
        String render() { return "== " + title + " ==\n" + body(); }
    }

    static class SalesReport extends Report {
        SalesReport() { super("Sales"); }
        @Override String body() { return "total: 4200"; }
    }

    public static void main(String[] args) {
        Report r = new SalesReport();
        System.out.println(r.render());
    }
}

public class Main {
    interface Readable { String read(); }
    interface Writable { void write(String text); }

    static class Notebook implements Readable, Writable {
        private String text = "";
        @Override public String read() { return text; }
        @Override public void write(String value) { text += value; }
    }

    public static void main(String[] args) {
        Notebook n = new Notebook();
        n.write("Java ");
        n.write("interfaces");
        Readable r = n;
        System.out.println(r.read());
        System.out.println(n instanceof Writable);
    }
}

