lab.solution:
import java.util.Scanner;

public class Main {
    interface Payment {
        String pay(double amount);
    }

    static class UpiPayment implements Payment {
        @Override public String pay(double amount) { return String.format("upi paid %.2f", amount); }
    }

    static class CardPayment implements Payment {
        @Override public String pay(double amount) { return String.format("card paid %.2f", amount); }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String kind = sc.next();
        double amount = sc.nextDouble();
        Payment p = kind.equals("upi") ? new UpiPayment() : new CardPayment();
        System.out.println(p.pay(amount));
    }
}
